import {
  Controller,
  Post,
  Body,
  Param,
  Get,
  UseGuards,
  Req,
  Res,
  Headers,
  BadRequestException,
} from '@nestjs/common';
import { Request } from 'express';
import { Response } from 'express';
import { PaymentsService } from './payments.service';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { Public } from '../auth/decorators/public.decorator';
import {
  CreateStripeIntentDto,
  CreateStripeCheckoutDto,
  CreateKonnectPaymentDto,
  CreatePayPalPaymentDto,
} from './dto/payment.dto';
import { JwtPayload } from '../auth/jwt.strategy';

type ReqWithUser = Request & { user: JwtPayload };

function renderPayPalReturnPage(title: string, message: string) {
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${title}</title>
    <style>
      body { font-family: Arial, sans-serif; margin: 0; min-height: 100vh; display: grid; place-items: center; background: #f7f7f7; color: #1f2937; }
      .card { max-width: 520px; margin: 24px; padding: 28px; background: #fff; border: 1px solid #e5e7eb; border-radius: 16px; box-shadow: 0 8px 30px rgba(0,0,0,.06); text-align: center; }
      h1 { margin: 0 0 12px; font-size: 24px; }
      p { margin: 0; line-height: 1.6; }
      .subtle { margin-top: 16px; color: #6b7280; font-size: 14px; }
    </style>
  </head>
  <body>
    <div class="card">
      <h1>${title}</h1>
      <p>${message}</p>
      <p class="subtle">You can close this tab and return to the app.</p>
    </div>
  </body>
</html>`;
}

@Controller('payments')
export class PaymentsController {
  constructor(private readonly paymentsService: PaymentsService) {}

  // =========================
  // STRIPE INTENT
  // =========================
  @Post('create-intent')
  @UseGuards(JwtAuthGuard)
  async createStripeIntent(
    @Req() req: ReqWithUser,
    @Body() dto: CreateStripeIntentDto,
  ) {
    return this.paymentsService.createStripeIntent({
      clientId: req.user.sub,
      restaurantId: dto.restaurantId,
      offerId: dto.offerId,
      items: dto.items,
      total: dto.total,
      collectionMethod: dto.collectionMethod,
      deliveryAddress: dto.deliveryAddress,
      deliveryPhone: dto.deliveryPhone,
      deliveryFee: dto.deliveryFee,
      email: dto.email,
      orderId: dto.orderId,
    });
  }

  // =========================
  // STRIPE CHECKOUT
  // =========================
  @Post('stripe/checkout')
  @UseGuards(JwtAuthGuard)
  async createStripeCheckout(
    @Req() req: ReqWithUser,
    @Body() dto: CreateStripeCheckoutDto,
  ) {
    return this.paymentsService.createStripeCheckoutSession({
      clientId: req.user.sub,
      restaurantId: dto.restaurantId,
      offerId: dto.offerId,
      items: dto.items,
      total: dto.total,
      collectionMethod: dto.collectionMethod,
      deliveryAddress: dto.deliveryAddress,
      deliveryPhone: dto.deliveryPhone,
      deliveryFee: dto.deliveryFee,
      email: dto.email,
      successUrl: dto.successUrl,
      cancelUrl: dto.cancelUrl,
      orderId: dto.orderId,
    });
  }

  // =========================
  // KONNECT PAYMENT
  // =========================
  @Post('konnect')
  @UseGuards(JwtAuthGuard)
  async createKonnectPayment(
    @Req() req: ReqWithUser,
    @Body() dto: CreateKonnectPaymentDto,
  ) {
    console.log('[KONNECT CONTROLLER] Received request:', dto);
    if (!dto.orderId || !dto.firstName || !dto.lastName || !dto.email) {
      throw new BadRequestException('Missing required fields');
    }

    const result = await this.paymentsService.createKonnectPayment({
      orderId: dto.orderId,
      userId: req.user.sub,
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      phone: dto.phone,
    });
    console.log('[KONNECT CONTROLLER] Result:', result);
    return result;
  }

  // =========================
  // PAYPAL PAYMENT
  // =========================
  @Post('paypal')
  @UseGuards(JwtAuthGuard)
  async createPayPalPayment(
    @Req() req: ReqWithUser,
    @Body() dto: CreatePayPalPaymentDto,
  ) {
    if (!dto.orderId) {
      throw new BadRequestException('Order ID is required');
    }

    return this.paymentsService.createPayPalPayment({
      orderId: dto.orderId,
      userId: req.user.sub,
      amount: dto.amount,
      returnUrl: dto.returnUrl,
      cancelUrl: dto.cancelUrl,
    });
  }

  // =========================
  // KONNECT VERIFY
  // =========================
  @Get('konnect/:paymentId/verify/:orderId')
  @UseGuards(JwtAuthGuard)
  async verifyKonnectPayment(
    @Req() req: ReqWithUser,
    @Param('paymentId') paymentId: string,
    @Param('orderId') orderId: string,
  ) {
    return this.paymentsService.verifyKonnectPayment(
      paymentId,
      orderId,
      req.user.sub,
    );
  }

  // =========================
  // PAYPAL CAPTURE
  // =========================
  @Post('paypal/:paypalOrderId/capture/:orderId')
  @UseGuards(JwtAuthGuard)
  async capturePayPalPayment(
    @Req() req: ReqWithUser,
    @Param('paypalOrderId') paypalOrderId: string,
    @Param('orderId') orderId: string,
  ) {
    return this.paymentsService.capturePayPalPayment(
      paypalOrderId,
      orderId,
      req.user.sub,
    );
  }

  @Post('confirm-stripe/:orderId/:paymentIntentId')
  @UseGuards(JwtAuthGuard)
  async confirmStripePayment(
    @Req() req: ReqWithUser,
    @Param('orderId') orderId: string,
    @Param('paymentIntentId') paymentIntentId: string,
  ) {
    return this.paymentsService.confirmStripePayment(
      paymentIntentId,
      req.user.sub,
    );
  }

  // =========================
  // STRIPE WEBHOOK
  // =========================
  @Post('webhooks/stripe')
  async stripeWebhook(
    @Req() req: Request & { body: Buffer },
    @Headers('stripe-signature') signature: string,
  ) {
    if (!signature) {
      throw new BadRequestException('Missing stripe-signature header');
    }
    return this.paymentsService.handleStripeWebhook(req.body, signature);
  }

  // =========================
  // STRIPE CHECKOUT CONFIRM
  // =========================
  @Get('stripe/checkout/:sessionId/confirm')
  @UseGuards(JwtAuthGuard)
  async confirmStripeCheckout(
    @Req() req: ReqWithUser,
    @Param('sessionId') sessionId: string,
  ) {
    return this.paymentsService.confirmStripeCheckoutSession(
      sessionId,
      req.user.sub,
    );
  }
  // =========================
  // PAYPAL RETURN PAGES
  // =========================
  @Public()
  @Get('paypal/success')
  async paypalSuccess(@Req() req: Request, @Res() res: Response) {
    try {
      const paypalOrderId = req.query.token as string;
      const orderId = req.query.orderId as string;

      if (!paypalOrderId || !orderId) {
        throw new BadRequestException('Missing parameters');
      }

      // Use public capture - no JWT required for PayPal redirect
      await this.paymentsService.capturePayPalPaymentPublic(
        paypalOrderId,
        orderId,
      );

      // Check if returnUrl is a deep link (for mobile apps)
      const returnUrl = req.query.returnUrl as string;
      if (returnUrl && returnUrl.startsWith('fiftyfood://')) {
        return res.redirect(returnUrl);
      }
      // For web: show a success page that auto-closes the tab
      return res.status(200).send(`
        <html><head><title>Payment Successful</title></head>
        <body style="display:flex;align-items:center;justify-content:center;min-height:100vh;font-family:sans-serif;background:#f0fdf4;">
          <div style="text-align:center;">
            <div style="font-size:64px;margin-bottom:16px;">✅</div>
            <h1 style="color:#16a34a;margin-bottom:8px;">Payment Successful!</h1>
            <p style="color:#6b7280;">You can close this tab and return to the app.</p>
          </div>
          <script>setTimeout(()=>window.close(),2000);</script>
        </body></html>
      `);
    } catch (error) {
      // Check if returnUrl is a deep link (for mobile apps)
      const returnUrl = req.query.returnUrl as string;
      if (returnUrl && returnUrl.startsWith('fiftyfood://')) {
        return res.redirect(returnUrl);
      }
      // If already captured, still show success
      if (
        (error as Error).message?.includes('ALREADY_CAPTURED') ||
        (error as Error).message?.includes('DUPLICATE_CAPTURE') ||
        (error as Error).message?.includes('already_processed')
      ) {
        return res.status(200).send(`
          <html><head><title>Payment Successful</title></head>
          <body style="display:flex;align-items:center;justify-content:center;min-height:100vh;font-family:sans-serif;background:#f0fdf4;">
            <div style="text-align:center;">
              <div style="font-size:64px;margin-bottom:16px;">✅</div>
              <h1 style="color:#16a34a;margin-bottom:8px;">Payment Successful!</h1>
              <p style="color:#6b7280;">You can close this tab and return to the app.</p>
            </div>
            <script>setTimeout(()=>window.close(),2000);</script>
          </body></html>
        `);
      }
      return res.status(200).send(`
        <html><head><title>Payment Failed</title></head>
        <body style="display:flex;align-items:center;justify-content:center;min-height:100vh;font-family:sans-serif;background:#fef2f2;">
          <div style="text-align:center;">
            <div style="font-size:64px;margin-bottom:16px;">❌</div>
            <h1 style="color:#dc2626;margin-bottom:8px;">Payment Failed</h1>
            <p style="color:#6b7280;">Please close this tab and try again.</p>
          </div>
        </body></html>
      `);
    }
  }

  @Get('paypal/cancel')
  async paypalCancel(@Req() req: Request, @Res() res: Response) {
    // Check if cancelUrl is a deep link (for mobile apps)
    const cancelUrl = req.query.cancelUrl as string;
    if (cancelUrl && cancelUrl.startsWith('fiftyfood://')) {
      return res.redirect(cancelUrl);
    }
    return res
      .status(200)
      .type('html')
      .send(
        renderPayPalReturnPage(
          'PayPal payment cancelled',
          'The payment was cancelled or not completed.',
        ),
      );
  }
}

import { Injectable, BadRequestException, Logger } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { StripeService } from './services/stripe.service';
import { KonnectService } from './services/konnect.service';
import { PayPalService } from './services/paypal.service';
import { OrderStatus, Prisma } from '@prisma/client';
import { NotificationsService } from '../notifications/notifications.service';

@Injectable()
export class PaymentsService {
  private readonly logger = new Logger(PaymentsService.name);

  constructor(
    private prisma: PrismaService,
    private stripeService: StripeService,
    private konnectService: KonnectService,
    private paypalService: PayPalService,
    private notificationsService: NotificationsService,
  ) {}

  private async findAndAuthorizeOrder(orderId: string, userId: string) {
    const order = await this.prisma.order.findUnique({
      where: { id: orderId },
    });
    if (!order) throw new BadRequestException('Order not found');
    if (order.clientId !== userId)
      throw new BadRequestException('Unauthorized');
    return order;
  }

  // =========================
  // STRIPE PAYMENT INTENT (no order created yet — created by webhook on success)
  // =========================
  async createStripeIntent(params: {
    clientId: string;
    restaurantId: string;
    offerId: string;
    items: unknown;
    total: number;
    collectionMethod?: string;
    deliveryAddress?: string;
    deliveryPhone?: string;
    deliveryFee?: number;
    email?: string;
    orderId?: string;
  }) {
    const verifiedTotal = await this.getVerifiedTotal(
      params.offerId,
      params.items,
      params.deliveryFee,
    );

    const intent = await this.stripeService.createPaymentIntent({
      orderData: {
        clientId: params.clientId,
        restaurantId: params.restaurantId,
        offerId: params.offerId,
        items: params.items,
        total: verifiedTotal,
        collectionMethod: params.collectionMethod,
        deliveryAddress: params.deliveryAddress,
        deliveryPhone: params.deliveryPhone,
        deliveryFee: params.deliveryFee,
      },
      amount: verifiedTotal,
      email: params.email,
      orderId: params.orderId,
    });

    return intent;
  }

  // =========================
  // KONNECT PAYMENT
  // =========================
  async createKonnectPayment(params: {
    orderId: string;
    userId: string;
    firstName: string;
    lastName: string;
    email: string;
    phone?: string;
  }) {
    const order = await this.findAndAuthorizeOrder(
      params.orderId,
      params.userId,
    );

    const konnectPayment = await this.konnectService.createPayment({
      orderId: params.orderId,
      amount: order.total,
      firstName: params.firstName,
      lastName: params.lastName,
      email: params.email,
      phone: params.phone,
    });

    await this.prisma.order.update({
      where: { id: params.orderId },
      data: {
        paymentMethod: 'D17',
      },
    });

    return {
      paymentUrl: konnectPayment.paymentUrl,
      paymentId: konnectPayment.paymentId,
    };
  }

  // =========================
  // PAYPAL PAYMENT
  // =========================
  async createPayPalPayment(params: {
    orderId: string;
    userId: string;
    amount?: number;
    returnUrl?: string;
    cancelUrl?: string;
  }) {
    const order = await this.findAndAuthorizeOrder(
      params.orderId,
      params.userId,
    );

    const paypalOrder = await this.paypalService.createOrder({
      orderId: params.orderId,
      amount: order.total,
      returnUrl: params.returnUrl,
      cancelUrl: params.cancelUrl,
    });

    await this.prisma.order.update({
      where: { id: params.orderId },
      data: {
        paymentMethod: 'PAYPAL',
        paymentDetails: {
          provider: 'paypal',
          paypalOrderId: paypalOrder.paypalOrderId,
          approvalUrl: paypalOrder.approvalUrl,
          mode: paypalOrder.mode,
        } as Prisma.InputJsonValue,
      },
    });

    return {
      approvalUrl: paypalOrder.approvalUrl,
      paypalOrderId: paypalOrder.paypalOrderId,
    };
  }

  // =========================
  // STRIPE CONFIRM INTENT (mobile fallback — webhook is source of truth)
  // =========================
  async confirmStripePayment(
    paymentIntentId: string,
    userId: string,
  ): Promise<{
    status: string;
    orderId?: string;
    orderStatus?: string;
    amount?: number;
  }> {
    const confirmation =
      await this.stripeService.confirmPayment(paymentIntentId);
    this.logger.log(`Stripe mobile confirm status: ${confirmation.status}`);

    if (confirmation.status === 'succeeded') {
      const orderId = confirmation.orderId;
      if (orderId) {
        await this.updateOrderStatus(orderId, 'CONFIRMED');
        await this.prisma.order.update({
          where: { id: orderId },
          data: {
            paymentDetails: {
              stripePaymentIntentId: paymentIntentId,
              provider: 'stripe',
              confirmedAt: new Date().toISOString(),
            } as Prisma.InputJsonValue,
          },
        });
        return {
          status: confirmation.status,
          orderId,
          amount: confirmation.amount,
        };
      }
    }

    return { status: confirmation.status, amount: confirmation.amount };
  }

  // =========================
  // STRIPE CHECKOUT SESSION
  // =========================
  async createStripeCheckoutSession(params: {
    clientId: string;
    restaurantId: string;
    offerId: string;
    items: unknown;
    total: number;
    collectionMethod?: string;
    deliveryAddress?: string;
    deliveryPhone?: string;
    deliveryFee?: number;
    email?: string;
    successUrl?: string;
    cancelUrl?: string;
    orderId?: string;
  }) {
    const verifiedTotal = await this.getVerifiedTotal(
      params.offerId,
      params.items,
      params.deliveryFee,
    );

    const session = await this.stripeService.createCheckoutSession({
      orderData: {
        clientId: params.clientId,
        restaurantId: params.restaurantId,
        offerId: params.offerId,
        items: params.items,
        total: verifiedTotal,
        collectionMethod: params.collectionMethod,
        deliveryAddress: params.deliveryAddress,
        deliveryPhone: params.deliveryPhone,
        deliveryFee: params.deliveryFee,
        orderId: params.orderId,
      },
      amount: verifiedTotal,
      email: params.email,
      successUrl: params.successUrl,
      cancelUrl: params.cancelUrl,
      orderId: params.orderId,
    });

    return session;
  }

  // =========================
  // STRIPE CHECKOUT CONFIRM (poll fallback — webhook is the source of truth)
  // =========================
  async confirmStripeCheckoutSession(
    sessionId: string,
    userId: string,
  ): Promise<{
    status: string;
    orderId?: string;
    orderStatus?: string;
    amount?: number;
  }> {
    const confirmation =
      await this.stripeService.confirmCheckoutSession(sessionId);

    if (confirmation.status === 'paid') {
      let order = null;

      // First: try to find order by ID from metadata (if pre-created)
      if (confirmation.metadata?.orderId) {
        order = await this.prisma.order.findUnique({
          where: { id: confirmation.metadata.orderId },
        });
      }

      // Second: try to find by stripeSessionId in paymentDetails (webhook created)
      if (!order) {
        order = await this.prisma.order.findFirst({
          where: {
            paymentDetails: { path: ['stripeSessionId'], equals: sessionId },
          },
        });
      }

      if (order) {
        // If order is not confirmed yet, confirm it now (webhook might have missed it)
        if (order.status !== 'CONFIRMED') {
          this.logger.log(`Confirming order ${order.id} via Stripe polling`);
          try {
            await this.updateOrderStatus(order.id, 'CONFIRMED');
          } catch (err) {
            this.logger.error(`Failed to confirm order ${order.id}: ${err}`);
            return {
              status: 'error',
              orderId: order.id,
              orderStatus: order.status,
            };
          }
          // Refresh order to get updated status
          const refreshed = await this.prisma.order.findUnique({
            where: { id: order.id },
          });
          return {
            status: 'paid',
            orderId: order.id,
            orderStatus: refreshed?.status ?? 'CONFIRMED',
            amount: confirmation.amount,
          };
        }
        return {
          status: 'paid',
          orderId: order.id,
          orderStatus: order.status,
          amount: confirmation.amount,
        };
      }

      // Payment succeeded but order not found/created
      this.logger.warn(
        `Stripe payment paid but order not found for session ${sessionId}`,
      );
      return { status: 'order_not_found' };
    }

    return { status: confirmation.status };
  }

  // =========================
  // KONNECT VERIFY
  // =========================
  async verifyKonnectPayment(
    paymentId: string,
    orderId: string,
    userId?: string,
  ) {
    const order = await this.prisma.order.findUnique({
      where: { id: orderId },
    });
    if (!order) throw new BadRequestException('Order not found');
    if (userId && order.clientId !== userId)
      throw new BadRequestException('Unauthorized');

    if (order.status !== OrderStatus.PENDING) {
      return { status: 'already_processed', orderStatus: order.status };
    }

    const verification = await this.konnectService.verifyPayment(paymentId);

    if (verification.orderId && verification.orderId !== orderId) {
      throw new BadRequestException('Payment does not belong to this order');
    }

    if (verification.isSuccessful) {
      await this.updateOrderStatus(orderId, 'CONFIRMED');
    } else {
      await this.updateOrderStatus(orderId, 'CANCELLED');
    }

    return verification;
  }

  // =========================
  // PAYPAL CAPTURE
  // =========================
  async capturePayPalPayment(
    paypalOrderId: string,
    orderId: string,
    userId?: string,
  ) {
    const order = await this.prisma.order.findUnique({
      where: { id: orderId },
    });
    if (!order) throw new BadRequestException('Order not found');
    if (userId && order.clientId !== userId)
      throw new BadRequestException('Unauthorized');

    if (order.status !== OrderStatus.PENDING) {
      return { status: 'already_processed', orderStatus: order.status };
    }

    return this._doPayPalCapture(paypalOrderId, orderId);
  }

  // Internal capture method used by both JWT and non-JWT flows
  private async _doPayPalCapture(paypalOrderId: string, orderId: string) {
    const capture = await this.paypalService.captureOrder(paypalOrderId);

    if (capture.orderId && capture.orderId !== orderId) {
      throw new BadRequestException('PayPal order does not match');
    }

    const order = await this.prisma.order.findUniqueOrThrow({
      where: { id: orderId },
    });

    const existingDetails =
      (order.paymentDetails as Record<string, unknown>) ?? {};
    await this.prisma.order.update({
      where: { id: orderId },
      data: {
        paymentDetails: {
          ...existingDetails,
          captureStatus: capture.status,
          capturedAmount: capture.amount,
          mode: capture.mode,
        } as Prisma.InputJsonValue,
      },
    });

    if ((capture as { needsApproval?: boolean }).needsApproval) {
      return capture;
    }

    if (capture.isSuccessful) {
      // Decrement offer quantity when payment is successful
      let quantityOrdered = 1;
      try {
        const parsed: unknown =
          typeof order.items === 'string'
            ? (JSON.parse(order.items) as unknown)
            : order.items;
        quantityOrdered = this.extractQuantity(parsed);
      } catch {
        /* default quantity 1 */
      }

      await this.prisma.$transaction(async (tx) => {
        // Decrement offer quantity
        const reserved = await tx.offer.updateMany({
          where: {
            id: order.offerId,
            status: 'ACTIVE',
            quantity: { gte: quantityOrdered },
          },
          data: { quantity: { decrement: quantityOrdered } },
        });
        if (reserved.count === 0) {
          throw new BadRequestException('Offer no longer available');
        }
        // Update order status
        await tx.order.update({
          where: { id: orderId },
          data: { status: 'CONFIRMED' },
        });
        // Mark as sold out if quantity reaches 0
        await tx.offer.updateMany({
          where: { id: order.offerId, quantity: { lte: 0 } },
          data: { status: 'SOLD_OUT' },
        });
      });
    } else {
      await this.updateOrderStatus(orderId, 'CANCELLED');
    }

    return capture;
  }

  // Public capture for PayPal redirect (no JWT required)
  async capturePayPalPaymentPublic(paypalOrderId: string, orderId: string) {
    // Verify order exists and is pending
    const order = await this.prisma.order.findUnique({
      where: { id: orderId },
    });

    if (!order) throw new BadRequestException('Order not found');
    if (order.status !== 'PENDING') {
      // Already processed, return current status
      return {
        isSuccessful: order.status === 'CONFIRMED',
        status: order.status,
        alreadyProcessed: true,
      };
    }

    return this._doPayPalCapture(paypalOrderId, orderId);
  }

  // =========================
  // STRIPE WEBHOOK (source of truth — creates the order on payment)
  // =========================
  async handleStripeWebhook(rawBody: Buffer, signature: string) {
    const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;
    if (!webhookSecret) {
      throw new BadRequestException('Stripe webhook secret not configured');
    }

    let event: unknown;
    try {
      event = this.stripeService.constructWebhookEvent(
        rawBody,
        signature,
        webhookSecret,
      );
    } catch {
      throw new BadRequestException('Invalid Stripe webhook signature');
    }

    if (!event || typeof event !== 'object') {
      throw new BadRequestException('Invalid Stripe webhook payload');
    }

    const eventObj = event as {
      type?: string;
      data?: { object?: Record<string, unknown> };
    };
    const eventType = eventObj.type;

    if (typeof eventType !== 'string') {
      throw new BadRequestException('Invalid Stripe webhook payload type');
    }

    this.logger.log(`Stripe webhook received: ${eventType}`);

    switch (eventType) {
      case 'payment_intent.succeeded': {
        const intent = eventObj.data?.object;
        const metadata =
          intent &&
          typeof intent.metadata === 'object' &&
          intent.metadata !== null
            ? (intent.metadata as Record<string, unknown>)
            : undefined;
        const metadataOrderId =
          typeof metadata?.orderId === 'string' ? metadata.orderId : undefined;
        const intentId = typeof intent?.id === 'string' ? intent.id : 'unknown';

        if (metadataOrderId) {
          // Order was pre-created — just confirm it
          this.logger.log(
            `Order ${metadataOrderId} confirmed via Stripe webhook (payment_intent)`,
          );
          await this.updateOrderStatus(metadataOrderId, 'CONFIRMED');
          await this.prisma.order.update({
            where: { id: metadataOrderId },
            data: {
              paymentDetails: {
                stripePaymentIntentId: intentId,
                provider: 'stripe',
              } as Prisma.InputJsonValue,
            },
          });
        } else {
          this.logger.warn(
            `Stripe webhook: No orderId in payment_intent ${intentId}`,
          );
        }
        break;
      }
      case 'checkout.session.completed': {
        const session = eventObj.data?.object;
        const metadata =
          session &&
          typeof session.metadata === 'object' &&
          session.metadata !== null
            ? (session.metadata as Record<string, unknown>)
            : undefined;
        const metadataOrderId =
          typeof metadata?.orderId === 'string' ? metadata.orderId : undefined;
        const paymentStatus =
          typeof session?.payment_status === 'string'
            ? session.payment_status
            : undefined;
        const sessionId = typeof session?.id === 'string' ? session.id : undefined;

        this.logger.log(
          `checkout.session.completed: payment_status=${paymentStatus ?? 'unknown'}, metadata.orderId=${metadataOrderId ?? 'unknown'}`,
        );
        if (paymentStatus === 'paid') {
          // First: check if order was pre-created by orderId from metadata
          let order = null;
          if (metadataOrderId) {
            order = await this.prisma.order.findUnique({
              where: { id: metadataOrderId },
            });
            this.logger.log(
              `Found order by metadata.orderId: ${order ? order.id : 'null'}`,
            );
          }

          // Second: check by stripeSessionId in paymentDetails
          if (!order) {
            order = await this.prisma.order.findFirst({
              where: {
                paymentDetails: {
                  path: ['stripeSessionId'],
                  equals: sessionId,
                },
              },
            });
            this.logger.log(
              `Found order by stripeSessionId: ${order ? order.id : 'null'}`,
            );
          }

          if (!order) {
            // No existing order found - this shouldn't happen with new flow
            this.logger.warn(
              `Stripe webhook: No order found for session ${sessionId ?? 'unknown'}`,
            );
          } else if (order.status !== 'CONFIRMED') {
            // Order exists but not confirmed - confirm it (will decrement quantity and send notification)
            this.logger.log(
              `Order ${order.id} confirmed via Stripe webhook (checkout.session)`,
            );
            await this.updateOrderStatus(order.id, 'CONFIRMED');
            // Update payment details separately
            await this.prisma.order.update({
              where: { id: order.id },
              data: {
                paymentDetails: {
                  ...(order.paymentDetails as object),
                  stripeSessionId: sessionId,
                  provider: 'stripe',
                } as Prisma.InputJsonValue,
              },
            });
          }
        }
        break;
      }
      default:
        this.logger.log(`Unhandled Stripe event: ${eventType}`);
    }

    return { received: true };
  }

  // =========================
  // PRICE VERIFICATION
  // =========================
  private async getVerifiedTotal(
    offerId: string,
    items: unknown,
    deliveryFee?: number,
  ): Promise<number> {
    const offer = await this.prisma.offer.findUnique({
      where: { id: offerId },
      select: { discountedPrice: true, status: true },
    });
    if (!offer) throw new BadRequestException('Offer not found');
    if (offer.status !== 'ACTIVE')
      throw new BadRequestException('Offer is no longer available');

    let quantity = 1;
    try {
      const parsed: unknown =
        typeof items === 'string' ? (JSON.parse(items) as unknown) : items;
      quantity = this.extractQuantity(parsed);
    } catch {
      /* default quantity 1 */
    }

    const itemsTotal = Math.round(offer.discountedPrice * quantity * 100) / 100;
    const fee = deliveryFee ?? 0;
    return Math.round((itemsTotal + fee) * 100) / 100;
  }

  // =========================
  // CORE STATUS UPDATE
  // =========================
  private async updateOrderStatus(
    orderId: string,
    orderStatus: 'CONFIRMED' | 'CANCELLED' | 'PENDING',
  ) {
    const order = await this.prisma.order.findUnique({
      where: { id: orderId },
    });
    if (!order) return;

    // Only update if status is actually changing
    if (order.status === orderStatus) return;

    // When confirming, decrement offer quantity first
    if (orderStatus === 'CONFIRMED') {
      let quantityOrdered = 1;
      try {
        const parsed: unknown =
          typeof order.items === 'string'
            ? (JSON.parse(order.items) as unknown)
            : order.items;
        quantityOrdered = this.extractQuantity(parsed);
      } catch {
        /* default quantity 1 */
      }

      this.logger.log(
        `Decrementing offer ${order.offerId} quantity by ${quantityOrdered}`,
      );
      await this.prisma.$transaction(async (tx) => {
        // Decrement offer quantity
        const reserved = await tx.offer.updateMany({
          where: {
            id: order.offerId,
            status: 'ACTIVE',
            quantity: { gte: quantityOrdered },
          },
          data: { quantity: { decrement: quantityOrdered } },
        });
        if (reserved.count === 0) {
          throw new BadRequestException('Offer no longer available');
        }
        this.logger.log(
          `Offer ${order.offerId} quantity decremented by ${quantityOrdered}`,
        );
        // Update order status
        await tx.order.update({
          where: { id: orderId },
          data: { status: 'CONFIRMED' },
        });
        // Mark as sold out if quantity reaches 0
        const soldOut = await tx.offer.updateMany({
          where: { id: order.offerId, quantity: { lte: 0 } },
          data: { status: 'SOLD_OUT' },
        });
        if (soldOut.count > 0) {
          this.logger.log(`Offer ${order.offerId} marked as SOLD_OUT`);
        }
      });

      this.logger.log(`Order ${orderId} confirmed - sending notification`);
      void this.notificationsService.notifyOrderCreated(orderId);
    } else {
      await this.prisma.order.update({
        where: { id: orderId },
        data: { status: orderStatus },
      });
    }
  }

  // =========================
  // ORDER LOOKUP (for controllers)
  // =========================
  async getOrderById(orderId: string) {
    return this.prisma.order.findUnique({
      where: { id: orderId },
      include: {
        client: {
          select: { email: true },
          include: { clientProfile: { select: { fullName: true } } },
        },
        restaurant: {
          select: { email: true },
          include: { restaurantProfile: { select: { restaurantName: true } } },
        },
        offer: { select: { description: true, photoUrl: true } },
      },
    });
  }

  private extractQuantity(items: unknown): number {
    const candidate = Array.isArray(items) ? (items as unknown[])[0] : items;
    if (!candidate || typeof candidate !== 'object') {
      return 1;
    }

    const quantityValue = (candidate as Record<string, unknown>).quantity;
    if (typeof quantityValue === 'number' && Number.isFinite(quantityValue)) {
      return Math.max(1, Math.floor(quantityValue));
    }

    return 1;
  }
}

import { Injectable, BadRequestException, Logger } from '@nestjs/common';
import Stripe from 'stripe';

@Injectable()
export class StripeService {
  private readonly logger = new Logger(StripeService.name);
  private stripe: InstanceType<typeof Stripe>;
  private stripePk: string;

  constructor() {
    const secretKey = process.env.STRIPE_SECRET_KEY || '';
    this.stripePk = process.env.STRIPE_PUBLISHABLE_KEY || '';

    if (!secretKey) {
      this.logger.warn('STRIPE_SECRET_KEY not configured');
    }

    this.stripe = new Stripe(secretKey, {
      apiVersion: '2026-04-22.dahlia',
    });
  }

  private ensureStripe() {
    if (!this.stripe) {
      throw new BadRequestException('Stripe is not configured');
    }
  }

  async createPaymentIntent(params: {
    orderData: Record<string, unknown>;
    amount: number;
    email?: string;
    orderId?: string;
  }) {
    this.ensureStripe();

    const metadata: Record<string, string> = params.orderId
      ? { orderId: params.orderId }
      : { orderData: JSON.stringify(params.orderData) };

    const paymentIntent = await this.stripe.paymentIntents.create({
      amount: Math.round(params.amount * 100),
      currency: 'eur',
      metadata,
      description: 'FiftyFood Order',
      receipt_email: params.email || undefined,
    });

    return {
      clientSecret: paymentIntent.client_secret,
      publishableKey: this.stripePk,
    };
  }

  async confirmPayment(paymentIntentId: string) {
    this.ensureStripe();

    const paymentIntent =
      await this.stripe.paymentIntents.retrieve(paymentIntentId);

    return {
      status: paymentIntent.status,
      amount: paymentIntent.amount / 100,
      orderId: paymentIntent.metadata?.orderId,
      metadata: paymentIntent.metadata,
    };
  }

  async createCheckoutSession(params: {
    orderData: Record<string, unknown>;
    amount: number;
    email?: string;
    successUrl?: string;
    cancelUrl?: string;
    orderId?: string;
  }) {
    this.ensureStripe();

    const baseUrl = process.env.PUBLIC_BACKEND_URL;
    if (!baseUrl) {
      throw new BadRequestException('PUBLIC_BACKEND_URL is not configured');
    }

    const successUrl =
      params.successUrl || `${baseUrl}/payments/stripe/checkout/success`;

    const cancelUrl =
      params.cancelUrl || `${baseUrl}/payments/stripe/checkout/cancel`;

    // Build metadata with orderId if provided
    const metadata: Record<string, string> = {
      orderData: JSON.stringify(params.orderData),
    };
    if (params.orderId) {
      metadata.orderId = params.orderId;
    }

    const sanitizedEmail =
      params.email &&
      params.email.trim().length > 0 &&
      params.email.includes('@')
        ? params.email.trim()
        : undefined;

    // Only set customer_email if valid
    const sessionConfig: Stripe.Checkout.SessionCreateParams = {
      mode: 'payment',
      payment_method_types: ['card'],
      line_items: [
        {
          price_data: {
            currency: 'eur',
            unit_amount: Math.round(params.amount * 100),
            product_data: {
              name: `FiftyFood Order`,
            },
          },
          quantity: 1,
        },
      ],
      success_url: successUrl,
      cancel_url: cancelUrl,
      ...(sanitizedEmail ? { customer_email: sanitizedEmail } : {}),
      metadata,
    };

    const session = await this.stripe.checkout.sessions.create(sessionConfig);

    return {
      sessionId: session.id,
      sessionUrl: session.url,
    };
  }

  async confirmCheckoutSession(sessionId: string) {
    this.ensureStripe();

    const session = await this.stripe.checkout.sessions.retrieve(sessionId);

    return {
      status: session.payment_status,
      orderId: session.metadata?.orderId,
      paymentIntentId: session.payment_intent,
      metadata: session.metadata,
      amount: session.amount_total ? session.amount_total / 100 : undefined,
    };
  }

  constructWebhookEvent(rawBody: Buffer, signature: string, secret: string) {
    return this.stripe.webhooks.constructEvent(rawBody, signature, secret);
  }
}
